def get_tiles(A):
    nr=(A.shape[0]+1)//4; nc=(A.shape[1]+1)//4
    return [[A[r*4:min(r*4+3,A.shape[0]),c*4:min(c*4+3,A.shape[1])] for c in range(nc)] for r in range(nr)]
T=get_tiles(A)
